# Tabbit's binary reader.
#
# Copied in beside the generated accessor so the emitted code needs nothing
# installed. Edit it in the Tabbit repository.
#
#
# Reads the .tcb files Tabbit's binary exporter writes:
#
#   fixed8      one byte
#   fixed32     four bytes, little endian
#   fixed64     eight bytes, little endian
#   varint32    seven bits per byte, high bit set while more bytes follow,
#               at most five bytes
#   counter32   zig-zag encoded int32 written as a varint32
#   string      counter32 byte length, then that many UTF-8 bytes
#
# One of several readers of one format the exporter defines. The conformance corpus is
# what keeps them agreeing.
#
# Two things about Python are worth knowing here. Its int is arbitrary precision, so a
# 64-bit value needs no special handling on the way in - unlike JavaScript, where the
# same value silently rounds. And it has no single-precision float, so a float32 read
# widens to a double; the value is exactly the one that was stored, just held in a
# wider type, and writing it back out at single precision is the caller's business.
#
# Nothing here needs anything installed, with one exception: an encrypted file needs the
# `cryptography` package. Byte-at-a-time Python is too slow to run a keystream over a
# table file, so that one path borrows a compiled implementation. The import happens
# inside the call that uses it, so a project whose files are not encrypted never meets it.

import hashlib
import hmac
import io
import struct

# Stamped at the head of every table file by the exporter.
# The format is column-oriented and self-describing: the header names every column
# and how long its block is, and a reader that meets a version it does not know stops
# rather than guessing.
FORMAT_VERSION = 107

# The wire's element types and kinds, as a column descriptor spells them.
ELEMENT_VARINT = 0
ELEMENT_BOOL = 1
ELEMENT_I32 = 2
ELEMENT_I64 = 3
ELEMENT_F32 = 4
ELEMENT_F64 = 5
ELEMENT_STRING = 6
ELEMENT_UUID = 7

KIND_SCALAR = 0
KIND_ARRAY = 1

# How a block's values are laid out. Raw is the layout 101 had; the others compress
# a column that repeats itself. spec/wire/tcb-v102-column-encoding.md is the contract.
ENCODING_RAW = 0
ENCODING_VARINT = 1
ENCODING_DELTA = 2
ENCODING_RLE = 3
ENCODING_DELTA_RLE = 4
ENCODING_DICT = 5
ENCODING_DICT_RLE = 6
ENCODING_DICT_FRONT = 7
ENCODING_DICT_FRONT_RLE = 8

# Composition rather than layout. An array block names an encoding for its elements and
# one for its rows' lengths, and a whole-number float block names the integer encoding its
# values travel under - so both are decoded by the cursor that already exists, one level
# down, and neither adds a decode step anywhere.
ENCODING_ARRAY = 9
ENCODING_WHOLE = 10

# A dictionary whose entries are built from a shared table of the pieces they are made of,
# which reaches what two values share in the middle and at the end where front coding can
# only reach what they share at the front.
ENCODING_DICT_SEGMENT = 11
ENCODING_DICT_SEGMENT_RLE = 12

#: An integer stream at the width its own range needs, over a base.
ENCODING_BITPACK = 13

# The file header, at fixed offsets whether or not the file is encrypted and whether or not
# it carries a MAC. spec/wire/tcb-mac-and-signature.md.
MAGIC_OFFSET = 0
VERSION_OFFSET = 4
FLAGS_OFFSET = 8
CIPHER_OFFSET = 9
NONCE_OFFSET = 10
MAC_OFFSET = 22
KEY_CHECK_OFFSET = 38

#: Where the body begins. The header before it is always this long.
HEADER_SIZE = 42

NONCE_SIZE = 12
MAC_SIZE = 16

#: The four bytes every table file starts with, and the key check under the cipher.
#:
#: The same four bytes serve twice. At offset zero they are the file format signature, in
#: the clear whether or not the file is encrypted. At the key check they are under the key,
#: so a file that decrypts to something else was written with a different key - which is the
#: one thing no structural check can tell from damage.
MAGIC = b"TCB\x00"

# Bit 0 of the flags byte: from the key check on, the file is ciphertext.
FLAG_ENCRYPTED = 0x01

# The cipher byte of a file that is not encrypted.
CIPHER_NONE = 0

# The only cipher the format defines.
CIPHER_CHACHA20 = 1


class Column:
    """One column as the file describes it."""

    __slots__ = ("tag", "element", "kind", "encoding", "byte_length", "nullable",
                 "element_nullable")

    def __init__(self, tag, element, kind, encoding, byte_length, nullable,
                 element_nullable=False):
        self.tag = tag
        self.element = element
        self.kind = kind
        self.encoding = encoding
        self.byte_length = byte_length

        # Whether the block begins with one presence bit per row, low bit first. Part of
        # the column's shape rather than a detail of its contents: a reader that does not
        # expect the bitmap reads it as values, so check_column refuses a disagreement the
        # same way it refuses a changed kind.
        self.nullable = nullable

        # Whether the block states, per element, which of an array's places hold a value.
        # Independent of `nullable`: a column may say either, or both.
        # spec/types/nullable-array-elements.md.
        self.element_nullable = element_nullable


class TcbError(Exception):
    """A table file is truncated, malformed, or not a table file."""


class RecordNotFoundError(Exception):
    """A lookup for a key no row carries.

    Raised by the generated `get_by_*_or_throw` lookups, which is where a caller has
    said the key has to be there. `find_by_*` answers the same question with None.

    Its own type rather than TcbError: nothing is wrong with the file, and a
    caller catching one of these is not catching the other.
    """


class Uuid:
    """A 128 bit identifier, stored in .NET Guid byte order.

    That order is not plain big-endian: the first three components are little endian
    and the trailing eight bytes are not, which is what __str__ has to account for.
    """

    # Component order matching .NET's Guid.ToString("D").
    _ORDER = (3, 2, 1, 0, 5, 4, 7, 6, 8, 9, 10, 11, 12, 13, 14, 15)

    __slots__ = ("raw",)

    def __init__(self, raw=None):
        self.raw = bytes(raw) if raw is not None else bytes(16)

    def __str__(self):
        out = []

        for position, index in enumerate(self._ORDER):
            if position in (4, 6, 8, 10):
                out.append("-")

            out.append("%02x" % self.raw[index])

        return "".join(out)

    def __repr__(self):
        return "Uuid('%s')" % self

    def __eq__(self, other):
        return isinstance(other, Uuid) and self.raw == other.raw

    def __hash__(self):
        return hash(self.raw)


class Reader:
    """Sequential reader over a table file's bytes.

    Every read either advances the cursor or raises, so a caller need not check a
    return value.
    """

    __slots__ = ("_data", "_position")

    def __init__(self, data):
        self._data = data
        self._position = 0

    @property
    def position(self):
        """Bytes consumed so far."""
        return self._position

    @property
    def remaining(self):
        """Bytes left to read."""
        return len(self._data) - self._position

    def _take(self, count):
        if self.remaining < count:
            raise TcbError(
                "table data ended after %d of %d bytes while %d more were expected"
                % (self._position, len(self._data), count))

        start = self._position
        self._position += count

        return self._data[start:self._position]

    def read_uint8(self):
        return self._take(1)[0]

    def read_bool(self):
        return self.read_uint8() != 0

    def read_int32(self):
        return struct.unpack_from("<i", self._take(4))[0]

    def read_uint32(self):
        return struct.unpack_from("<I", self._take(4))[0]

    def read_int64(self):
        return struct.unpack_from("<q", self._take(8))[0]

    def read_float(self):
        """A single-precision value.

        Read as its stored bit pattern and widened to Python's float, which is a
        double. The value is exactly the one that was stored; printing it at double
        precision shows digits the original 32 bits never carried, which is why the
        conformance comparison narrows before comparing.
        """
        return struct.unpack_from("<f", self._take(4))[0]

    def read_double(self):
        return struct.unpack_from("<d", self._take(8))[0]

    def read_string(self):
        length = self.read_counter32()

        if length < 0:
            raise TcbError("string length is negative")

        if length == 0:
            return ""

        return self._take(length).decode("utf-8")

    def read_counter64(self):
        """An int64 written in as few bytes as its magnitude needed, either sign.

        The base of a bit-packed block, which is a value of the column's own element
        type - an i64 column's base does not fit in thirty-two bits. One byte when it
        is zero, which is what most columns carry.
        """
        encoded = 0
        shift = 0

        while True:
            piece = self.read_uint8()
            encoded |= (piece & 0x7F) << shift

            if not piece & 0x80:
                break

            shift += 7
            if shift > 63:
                raise TcbError(
                    "a 64-bit variable length integer runs past ten bytes")

        value = (encoded >> 1) ^ -(encoded & 1)

        return value - 0x10000000000000000 if value >= 0x8000000000000000 else value

    def read_byte_stream(self, encoding, count, field_name):
        """A stream of bytes under one of the integer encodings.

        Which is what a packed block and a presence bitmap both end in. One reader for
        both, so a bitmap and a packed value block cannot disagree about the same bits.
        The count is known before the call in both cases, so nothing here reads a length.
        """
        if encoding == ENCODING_RAW:
            return self.read_bytes(count)

        if encoding > ENCODING_DELTA_RLE:
            raise TcbError(
                "%s: encoding %d cannot carry a packed byte stream"
                % (field_name, encoding))

        walking = encoding in (ENCODING_DELTA, ENCODING_DELTA_RLE)
        out = bytearray(count)

        filled = 0
        previous = 0

        # The first value of a delta stream is written outright; the rest are steps from
        # it. A run in a delta stream repeats the step, not the value, so it walks.
        if count and walking:
            previous = _as_byte(self.read_optimal_int32(), field_name)
            out[filled] = previous
            filled += 1

        while filled < count:
            run = 1
            step = 0
            value = 0

            if encoding == ENCODING_VARINT:
                value = _as_byte(self.read_optimal_int32(), field_name)
            elif encoding == ENCODING_DELTA:
                step = self.read_optimal_int32()
            elif encoding == ENCODING_RLE:
                run = self.read_counter32()
                value = _as_byte(self.read_optimal_int32(), field_name)
            else:  # ENCODING_DELTA_RLE
                run = self.read_counter32()
                step = self.read_optimal_int32()

            if run < 1 or run > count - filled:
                raise TcbError(
                    "%s: a run of %d cannot cover the %d bytes left"
                    % (field_name, run, count - filled))

            for _ in range(run):
                if walking:
                    previous = _as_byte(_wrap_int32(previous + step), field_name)
                    out[filled] = previous
                else:
                    out[filled] = value

                filled += 1

        return bytes(out)

    def read_bytes(self, count):
        """The next `count` bytes, uninterpreted.

        What a fixed-width dictionary entry is kept as, so that turning one into a
        value reconstructs exactly what the raw layout would have read.
        """
        return self._take(count)

    def skip(self, byte_count):
        """Advances past bytes without interpreting them: an unknown column's block.

        The column-oriented layout is what makes this one call the entirety of skipping.
        """
        if byte_count < 0 or byte_count > self.remaining:
            raise TcbError(
                "cannot skip %d bytes with %d remaining" % (byte_count, self.remaining))
        self._position += byte_count

    # Promotions: a member reading a file element narrower than itself. Only the
    # mathematically lossless directions exist; check_column already refused the rest.

    def read_i32_as(self, element):
        """An int32 member from i32 or varint."""
        return self.read_int32() if element == ELEMENT_I32 else self.read_counter32()

    def read_i64_as(self, element):
        """An int64 member from i64, i32 or varint."""
        if element == ELEMENT_I64:
            return self.read_int64()
        if element == ELEMENT_I32:
            return self.read_int32()
        return self.read_counter32()

    def read_f64_as(self, element):
        """A double member from f64, f32 or i32 - all exact in a double."""
        if element == ELEMENT_F64:
            return self.read_double()
        if element == ELEMENT_F32:
            return self.read_float()
        return self.read_int32()

    def read_datetime_ticks(self):
        """A timestamp as .NET ticks: 100 ns units since 0001-01-01.

        Ticks rather than a datetime, because the corpus reaches 0001-01-01 and
        9999-12-31 and a tick is finer than datetime's microsecond, so the conversion
        would lose both ends and the last two digits.
        """
        return self.read_int64()

    def read_duration_ticks(self):
        """A duration as .NET ticks.

        Ticks rather than a timedelta: TimeSpan.MaxValue is about 29,000 years and
        timedelta tops out near 2,700,000 days.
        """
        return self.read_int64()

    def read_uuid(self):
        return Uuid(self._take(16))

    def read_optimal_int32(self):
        """An int32 written in as few bytes as its magnitude needed, either sign."""
        encoded = self._read_varint32()

        # Undoes the zig-zag fold: the low bit carried the sign.
        return (encoded >> 1) ^ -(encoded & 1)

    def read_counter32(self):
        """A count, in the same encoding as read_optimal_int32."""
        return self.read_optimal_int32()

    def read_enum(self):
        """An enum value, which travels zig-zag encoded rather than fixed width."""
        return self.read_optimal_int32()

    def _read_varint32(self):
        value = 0

        for shift in range(0, 35, 7):
            byte = self.read_uint8()
            value |= (byte & 0x7F) << shift

            if not byte & 0x80:
                return value

        raise TcbError("varint32 is longer than five bytes")


def _as_byte(value, field_name):
    """A decoded value that has to be a byte, or the block is corrupt."""
    if value < 0 or value > 255:
        raise TcbError("%s: %d is not a byte" % (field_name, value))

    return value


def _wrap_int32(value):
    """The low 32 bits of a value, sign extended.

    Python's int never overflows, so the wrapping the delta encoding is defined
    over - two's complement, 32 bits - has to be spelled out.
    """
    value &= 0xFFFFFFFF

    return value - 0x100000000 if value >= 0x80000000 else value


def _read_front_coded_dictionary(reader, count, field_name):
    """A sorted dictionary whose entries state only what they do not share with the
    entry before them.

    Decoded into whole strings here rather than kept folded, because a row wants a
    string and the folding was only ever about the bytes on disk. The prefix is carried
    as bytes, not as a str: the entries are sorted by their UTF-8 bytes and a shared
    count is a count of bytes, which can land inside a character.
    """
    entries = []
    previous = b""

    for at in range(count):
        shared = reader.read_counter32()
        rest = reader.read_counter32()

        if shared < 0 or rest < 0 or shared > len(previous):
            raise TcbError(
                "%s: dictionary entry %d shares %d bytes with an entry of %d"
                % (field_name, at, shared, len(previous)))

        previous = previous[:shared] + reader.read_bytes(rest)
        entries.append(previous.decode("utf-8"))

    return entries


def _read_lengths(reader, encoding, row_count, field_name):
    """The lengths of an array column's rows, as their own encoded stream.

    A varint stream, so what may be chosen for it is what may be chosen for any varint
    column - each length as a counter32, or runs of them. Most columns have rows that are
    all the same length, which is one run.
    """
    if encoding == ENCODING_RAW:
        lengths = []

        for at in range(row_count):
            length = reader.read_counter32()

            if length < 0:
                raise TcbError(
                    "%s: row %d declares %d elements" % (field_name, at, length))

            lengths.append(length)

        return lengths

    if encoding != ENCODING_RLE:
        raise TcbError(
            "%s: encoding %d cannot carry an array column's row lengths"
            % (field_name, encoding))

    lengths = []

    while len(lengths) < row_count:
        run = reader.read_counter32()
        value = reader.read_optimal_int32()

        if run < 1 or run > row_count - len(lengths):
            raise TcbError(
                "%s: a run of %d lengths cannot cover the %d rows left in the column"
                % (field_name, run, row_count - len(lengths)))

        if value < 0:
            raise TcbError("%s: a row declares %d elements" % (field_name, value))

        lengths.extend([value] * run)

    return lengths


def _read_segment_dictionary(reader, field_name):
    """A dictionary whose entries are lists of references into a table of the pieces they
    are built from.

    Two reads and a concatenation: the table, which is front coded because its own entries
    share their fronts, and then each value as the pieces it is made of. The result is the
    same list of whole strings every other dictionary produces, so nothing downstream of
    here knows which kind it came from.
    """
    segment_count = reader.read_counter32()

    if segment_count < 0:
        raise TcbError("%s: the segment count is negative" % field_name)

    if segment_count > reader.remaining:
        raise TcbError(
            "%s: a segment table of %d entries is larger than the file can hold"
            % (field_name, segment_count))

    segments = []
    previous = b""

    for at in range(segment_count):
        shared = reader.read_counter32()
        rest = reader.read_counter32()

        if shared < 0 or rest < 0 or shared > len(previous):
            raise TcbError(
                "%s: segment %d shares %d bytes with an entry of %d"
                % (field_name, at, shared, len(previous)))

        previous = previous[:shared] + reader.read_bytes(rest)
        segments.append(previous)

    count = reader.read_counter32()

    if count < 0:
        raise TcbError("%s: the dictionary entry count is negative" % field_name)

    if count > reader.remaining:
        raise TcbError(
            "%s: a dictionary of %d entries is larger than the file can hold"
            % (field_name, count))

    entries = []

    for at in range(count):
        pieces = reader.read_counter32()

        if pieces < 0:
            raise TcbError(
                "%s: dictionary entry %d declares %d pieces" % (field_name, at, pieces))

        value = []

        for _ in range(pieces):
            index = reader.read_counter32()

            if index < 0 or index >= segment_count:
                raise TcbError(
                    "%s: segment index %d is out of range - the table holds %d entries"
                    % (field_name, index, segment_count))

            value.append(segments[index])

        entries.append(b"".join(value).decode("utf-8"))

    return entries


class ColumnCursor:
    """Reads one scalar column's values in row order, whatever the block's encoding.

    The generated row loop stays a row loop; this is the one place that knows how a
    delta accumulates, how long a run has left, or that a dictionary index is a
    reference into strings decoded once. That last one matters beyond file size: a
    hundred-thousand-row column with three distinct strings holds three str objects,
    not a hundred thousand.

    check_column has already refused any (element, encoding) pair the spec does not
    define, so the branches here do not re-litigate that.
    """

    __slots__ = ("_reader", "_field_name", "_element", "_encoding", "_dictionary",
                 "_value_dictionary", "_run_remaining", "_run_value", "_previous",
                 "_started", "_rows_remaining", "_lengths", "_length_at",
                 "_whole_numbers", "_packed", "_packed_width", "_packed_base",
                 "_packed_bit")

    def __init__(self, reader, column, row_count, field_name):
        self._reader = reader
        self._field_name = field_name
        self._element = column.element
        self._encoding = column.encoding

        # A run-length family's current run: what remains of it, and its value - which
        # is a plain value for RLE, a delta for DELTA_RLE, an index for DICT_RLE.
        self._run_remaining = 0
        self._run_value = 0

        # The delta family's accumulator, once started.
        self._previous = 0
        self._started = False

        # Values not yet handed out. A run that claims more than this is corrupt, and
        # catching it here names the field instead of leaving it to the block-end check.
        # For an array column this counts elements, not rows.
        self._rows_remaining = row_count

        # The block's dictionary, decoded once and handed out per row. One of the two is
        # filled when the block has a dictionary at all, chosen by the element: strings
        # become instances that rows then share, and a fixed-width element keeps its raw
        # bytes so that a value is reconstructed exactly as the raw layout would have
        # read it.
        self._dictionary = None
        self._value_dictionary = None

        # How many elements each row holds, decoded up front for an encoded array column.
        # Up front because the element stream follows the length stream in the block, so
        # every length has been read by the time the first element is. None for a raw
        # array, whose lengths are interleaved with its elements and read as they are
        # reached.
        self._lengths = None
        self._length_at = 0

        # Whether a float column's values are travelling as integers.
        self._whole_numbers = False

        # A bit-packed column's bytes, decoded up front, and where in them the next value
        # is. Up front because the bytes are themselves under an encoding and a value can
        # cross a byte boundary, so handing values out one at a time would mean carrying a
        # decoder and a bit offset that disagree about where they are.
        self._packed = None
        self._packed_width = 0
        self._packed_base = 0
        self._packed_bit = 0

        # An array column's block names an encoding for its elements and, where its rows
        # differ in length, one for the lengths. Both are encodings that already exist, so
        # all this does is read them and then go on being the element stream's cursor.
        if self._encoding == ENCODING_ARRAY:
            self._encoding = reader.read_uint8()

            if column.kind == KIND_ARRAY:
                self._lengths = _read_lengths(
                    reader, reader.read_uint8(), row_count, field_name)
                self._rows_remaining = sum(self._lengths)

        # A bit-packed column states the width its range needs, the base subtracted from
        # every value, and which encoding carries the packed bytes. Decoded here so that
        # handing values out is a shift and an add.
        if self._encoding == ENCODING_BITPACK:
            width = reader.read_uint8()
            base = reader.read_counter64()
            inner = reader.read_uint8()

            if width < 1 or width > 64:
                raise TcbError(
                    "%s: a bit width of %d is not between 1 and 64"
                    % (field_name, width))

            self._packed_width = width
            self._packed_base = base
            self._packed = reader.read_byte_stream(
                inner, (self._rows_remaining * width + 7) // 8, field_name)

            return

        # A float column whose values are all whole numbers carries them as integers and
        # says which integer encoding they travel under. From here down it is that
        # encoding's cursor, and only the handing out converts back.
        if self._encoding == ENCODING_WHOLE:
            inner = reader.read_uint8()

            if inner < ENCODING_VARINT or inner > ENCODING_DELTA_RLE:
                raise TcbError(
                    "%s: encoding %d cannot carry a whole-number column's values"
                    % (field_name, inner))

            self._encoding = inner
            self._whole_numbers = True

        # A segment dictionary is built once, here, and from then on the block is a
        # dictionary with an index stream like any other - so the row-by-row paths below
        # need to know nothing about it.
        if self._encoding in (ENCODING_DICT_SEGMENT, ENCODING_DICT_SEGMENT_RLE):
            self._dictionary = _read_segment_dictionary(reader, field_name)
            self._encoding = (
                ENCODING_DICT if self._encoding == ENCODING_DICT_SEGMENT
                else ENCODING_DICT_RLE)

            return

        plain_dictionary = self._encoding in (ENCODING_DICT, ENCODING_DICT_RLE)
        front_dictionary = self._encoding in (
            ENCODING_DICT_FRONT, ENCODING_DICT_FRONT_RLE)

        if not plain_dictionary and not front_dictionary:
            return

        count = reader.read_counter32()

        if count < 0:
            raise TcbError(
                "%s: the dictionary entry count is negative" % field_name)

        if front_dictionary:
            self._dictionary = _read_front_coded_dictionary(reader, count, field_name)
        elif self._element == ELEMENT_STRING:
            self._dictionary = [reader.read_string() for _ in range(count)]
        else:
            # A fixed-width element: an entry is the value's own bytes, taken as bytes
            # and turned into a value only when a row asks for one.
            width = 4 if self._element == ELEMENT_F32 else 8
            self._value_dictionary = [reader.read_bytes(width) for _ in range(count)]

    def next_length(self):
        """How many elements the next row of an array column holds.

        One call whichever way the block is laid out. An encoded array decoded every
        length before the first element was read, so this hands out what it already has;
        a raw one states each row's length in front of that row's elements, so this reads
        it where it stands.
        """
        if self._lengths is not None:
            if self._length_at >= len(self._lengths):
                raise TcbError(
                    "%s: the column has no more rows to read" % self._field_name)

            length = self._lengths[self._length_at]
            self._length_at += 1

            return length

        length = self._reader.read_counter32()

        if length < 0:
            raise TcbError(
                "%s: a row declares %d elements" % (self._field_name, length))

        return length

    def _next_packed(self):
        """The next value of a bit-packed stream: the packed bits, over the block's base.

        A value may cross a byte boundary, so this walks bits rather than bytes. The
        addition wraps, mirroring the writer's wrapping subtraction.
        """
        slot = 0
        packed = self._packed
        bit = self._packed_bit

        for at in range(self._packed_width):
            if packed[bit >> 3] >> (bit & 7) & 1:
                slot |= 1 << at
            bit += 1

        self._packed_bit = bit

        value = (self._packed_base + slot) & 0xFFFFFFFFFFFFFFFF

        return value - 0x10000000000000000 if value >= 0x8000000000000000 else value

    def next_i32(self):
        """The next int32 - which also serves enums, and reference indexes."""
        self._rows_remaining -= 1
        encoding = self._encoding

        if encoding == ENCODING_BITPACK:
            return _wrap_int32(self._next_packed())

        if encoding == ENCODING_RAW:
            if self._element == ELEMENT_I32:
                return self._reader.read_int32()
            return self._reader.read_optimal_int32()

        if encoding == ENCODING_VARINT:
            return self._reader.read_optimal_int32()

        if encoding == ENCODING_DELTA:
            # The addition wraps on purpose, mirroring the writer's wrapping
            # subtraction; together they are exact for every int32 pair.
            if self._started:
                self._previous = _wrap_int32(
                    self._previous + self._reader.read_optimal_int32())
            else:
                self._previous = self._reader.read_optimal_int32()
                self._started = True

            return self._previous

        if encoding == ENCODING_RLE:
            if self._run_remaining == 0:
                self._read_run()

            self._run_remaining -= 1
            return self._run_value

        # ENCODING_DELTA_RLE; check_column refused everything else.
        if not self._started:
            self._previous = self._reader.read_optimal_int32()
            self._started = True
            return self._previous

        if self._run_remaining == 0:
            self._read_run()

        self._run_remaining -= 1
        self._previous = _wrap_int32(self._previous + self._run_value)
        return self._previous

    def next_i64(self):
        """An int64 member: from an i64 column raw or through its dictionary, and from
        anything narrower by decoding an int32 and widening it.
        """
        if self._element != ELEMENT_I64:
            return self.next_i32()

        if self._encoding == ENCODING_BITPACK:
            self._rows_remaining -= 1
            return self._next_packed()

        if self._value_dictionary is not None:
            return struct.unpack_from("<q", self._next_value_entry())[0]

        self._rows_remaining -= 1
        return self._reader.read_int64()

    def next_f32(self):
        """A float member: raw, the dictionary entry's exact bit pattern, or a whole number.

        Widened to Python's float, which is a double - see Reader.read_float.
        """
        if self._whole_numbers:
            return float(self.next_i32())

        if self._value_dictionary is not None:
            return struct.unpack_from("<f", self._next_value_entry())[0]

        self._rows_remaining -= 1
        return self._reader.read_float()

    def next_f64(self):
        """A double member: from f64 or f32 - either of them raw or dictionary
        encoded - and from an i32 column by decoding and widening.
        """
        if self._whole_numbers:
            return float(self.next_i32())

        if self._element == ELEMENT_F64:
            if self._value_dictionary is not None:
                return struct.unpack_from("<d", self._next_value_entry())[0]

            self._rows_remaining -= 1
            return self._reader.read_double()

        if self._element == ELEMENT_F32:
            return self.next_f32()

        return self.next_i32()

    def next_bool(self):
        """A bool member: one byte raw, a run of them, or one packed bit."""
        if self._encoding in (ENCODING_RLE, ENCODING_BITPACK):
            return self.next_i32() != 0

        self._rows_remaining -= 1
        return self._reader.read_bool()

    def _next_value_entry(self):
        """The bytes of the next row's dictionary entry, for a fixed-width element."""
        self._rows_remaining -= 1

        if self._encoding == ENCODING_DICT:
            index = self._reader.read_counter32()
        else:
            # ENCODING_DICT_RLE; a fixed-width element reaches no other encoding here.
            if self._run_remaining == 0:
                self._read_run()

            self._run_remaining -= 1
            index = self._run_value

        return self._dictionary_entry(self._value_dictionary, index)

    def next_string(self):
        """The next string - the dictionary's instance where the block has one."""
        self._rows_remaining -= 1

        if self._encoding == ENCODING_RAW:
            return self._reader.read_string()

        if self._encoding in (ENCODING_DICT, ENCODING_DICT_FRONT):
            return self._dictionary_entry(self._dictionary, self._reader.read_counter32())

        # ENCODING_DICT_RLE and ENCODING_DICT_FRONT_RLE, whose dictionaries differ only
        # in how they were written down.
        if self._run_remaining == 0:
            self._read_run()

        self._run_remaining -= 1
        return self._dictionary_entry(self._dictionary, self._run_value)

    def next_same_i32(self, limit):
        """Up to `limit` rows that all hold the next value, as `(count, value)`.

        Always at least 1. This is what makes a run cost one call instead of one per
        row: the generated loop asks once, then assigns the value that many times. An
        encoding that cannot promise sameness cheaply answers 1, so the caller's loop
        is correct over every encoding and only faster over runs.
        """
        encoding = self._encoding

        if encoding == ENCODING_RLE:
            self._rows_remaining -= 1
            if self._run_remaining == 0:
                self._read_run()

            n = self._run_remaining if self._run_remaining < limit else limit
            self._run_remaining -= n
            self._rows_remaining -= n - 1

            return n, self._run_value

        if encoding == ENCODING_DELTA_RLE and self._started:
            self._rows_remaining -= 1
            if self._run_remaining == 0:
                self._read_run()

            if self._run_value == 0:
                # A zero-delta run is a run of one value.
                n = self._run_remaining if self._run_remaining < limit else limit
                self._run_remaining -= n
                self._rows_remaining -= n - 1

                return n, self._previous

            self._run_remaining -= 1
            self._previous = _wrap_int32(self._previous + self._run_value)

            return 1, self._previous

        return 1, self.next_i32()

    def next_same_string(self, limit):
        """The string counterpart of `next_same_i32`."""
        if self._encoding in (ENCODING_DICT_RLE, ENCODING_DICT_FRONT_RLE):
            self._rows_remaining -= 1
            if self._run_remaining == 0:
                self._read_run()

            n = self._run_remaining if self._run_remaining < limit else limit
            self._run_remaining -= n
            self._rows_remaining -= n - 1

            return n, self._dictionary_entry(self._dictionary, self._run_value)

        return 1, self.next_string()

    def _read_run(self):
        length = self._reader.read_counter32()

        # + 1 because the row this run was read for is already counted out of
        # _rows_remaining by its next_* call.
        if length < 1 or length > self._rows_remaining + 1:
            raise TcbError(
                "%s: a run of %d values cannot cover the %d rows left in the column"
                % (self._field_name, length, self._rows_remaining + 1))

        self._run_remaining = length
        self._run_value = self._reader.read_optimal_int32()

    def _dictionary_entry(self, entries, index):
        if index < 0 or index >= len(entries):
            raise TcbError(
                "%s: dictionary index %d is out of range - the dictionary holds %d entries"
                % (self._field_name, index, len(entries)))

        return entries[index]


def read_table_header(reader):
    """Reads and checks a table file's header.

    Returns (row_count, columns): the column descriptors the data blocks follow.
    """
    # Checked again here rather than only in `open`, because a reader can be handed bytes
    # that never went through it.
    if reader.read_uint32() != struct.unpack("<I", MAGIC)[0]:
        raise TcbError("the file does not begin with the table file signature")

    version = reader.read_uint32()
    if version != FORMAT_VERSION:
        raise TcbError(
            "table format version %d is not supported (expected %d)"
            % (version, FORMAT_VERSION))

    # Bit 0 included, not only the bits above it. `open` clears it on a file it has
    # decrypted, so meeting it set here means the bytes reached the reader without the key -
    # and saying so beats letting the block lengths make what they can of ciphertext. Any
    # other bit is a feature this build was written before.
    flags = reader.read_uint8()
    if flags & FLAG_ENCRYPTED:
        raise TcbError(
            "the table is encrypted and was not decrypted - pass the key through open first")

    if flags:
        raise TcbError("table declares unsupported features")

    # The cipher byte, the nonce, the MAC and the key check. `open` has dealt with all four
    # by now; what is left is to be standing at the body.
    reader.skip(HEADER_SIZE - CIPHER_OFFSET)

    count = reader.read_counter32()
    if count < 0:
        raise TcbError("table row count is negative")

    column_count = reader.read_counter32()
    if column_count < 0:
        raise TcbError("table column count is negative")

    columns = []
    for _ in range(column_count):
        tag = reader.read_counter32()
        wire = reader.read_uint8()
        encoding = reader.read_uint8()
        byte_length = reader.read_uint32()
        columns.append(
            Column(tag, wire & 0x0F, (wire >> 4) & 0x03, encoding, byte_length,
                   (wire & 0x40) != 0, (wire & 0x80) != 0))

    # What the descriptors say about the file, checked before anybody allocates for the
    # row count. The blocks are all that follows the header, so their declared lengths have
    # to add up to the bytes left. A raw block also costs at least one byte per
    # row - a varint's shortest form, an empty string's length prefix, a variable
    # array's counter - so a larger row count is one the exporter could not have
    # written. An encoded block has no such floor; its decode checks run sums and
    # dictionary bounds instead.

    available = reader.remaining
    declared = 0

    for column in columns:
        if column.byte_length < 0 or column.byte_length > available - declared:
            raise TcbError(
                "column tag %d declares %d bytes, which the file cannot hold"
                % (column.tag, column.byte_length))

        declared += column.byte_length

        if column.encoding == ENCODING_RAW and count > column.byte_length:
            raise TcbError(
                "the row count %d is larger than column tag %d can hold in its %d bytes"
                % (count, column.tag, column.byte_length))

    if declared != available:
        raise TcbError(
            "the columns declare %d bytes but %d follow the header" % (declared, available))

    return count, columns


def read_presence(reader, column, row_count):
    """A nullable column's presence bitmap, which sits at the front of its block.

    Empty for a column that is not optional, which is what lets the generated code call
    `is_present` without testing first.
    """
    if not column.nullable:
        return b""

    # The bitmap is a bit-packed boolean column of width one, so it carries an encoding
    # byte and is laid out by the same choice a packed value block uses. Its width and
    # base are known in advance, which is why it does not carry them.
    encoding = reader.read_uint8()

    return reader.read_byte_stream(
        encoding, (row_count + 7) // 8, "a presence bitmap")


def read_element_presence(reader, column):
    """A column's element bitmap, behind the row bitmap and in front of the values.

    Empty for a column that does not carry one. Its length is written ahead of it as a
    counter32, because a variable-length column's total is the sum of its row lengths and
    those live inside the value block - a reader meeting the bitmap first would have nothing
    to size it by. spec/types/nullable-array-elements.md.
    """
    if not column.element_nullable:
        return b""

    elements = reader.read_counter32()
    encoding = reader.read_uint8()

    return reader.read_byte_stream(
        encoding, (elements + 7) // 8, "an element presence bitmap")


def is_present(presence, row):
    """Whether a row has a value, for a column that says which do.

    An empty bitmap means the column is not optional, and then every row has one.
    """
    return not presence or (presence[row >> 3] & (1 << (row & 7))) != 0


def check_column(column, field_name, kind, nullable, accepted,
                 element_nullable=False):
    """That a column is what the generated member expects, or a lossless promotion.

    Refusal is by name and both types, never by reading anyway.
    """
    # The same statement about the other bitmap: code not expecting one would read it as
    # values. spec/types/nullable-array-elements.md.
    if column.element_nullable != element_nullable:
        raise TcbError(
            "%s: the file and the generated member disagree about whether this column's "
            "elements are optional. The schema changed; regenerate the code or rebuild the "
            "data." % (field_name,))

    # Nullability is part of the shape: a file that says optional puts a presence bitmap in
    # front of the block, and code not expecting one would read the bitmap as values. So
    # adding or removing a `?` is a schema change like any other, caught here rather than in
    # whatever the misread bytes happened to mean.
    if column.nullable != nullable:
        raise TcbError(
            "%s: the file and the generated member disagree about whether this column is "
            "optional. The schema changed; regenerate the code or rebuild the data."
            % (field_name,))

    # A negative count says the member claims no length: how many elements a row holds is
    # what the file states. The kind is still the member's claim.
    # spec/types/nullable-array-elements.md.
    if column.kind != kind:
        raise TcbError(
            "%s: the file's column (kind %d) does not match the generated member "
            "(kind %d). The schema changed shape; regenerate the code or rebuild "
            "the data." % (field_name, column.kind, kind))

    # An encoding this build cannot decode - or one the spec does not define for
    # this element - is refused by name, exactly like an element it cannot read.
    # An unknown column's encoding never gets here - a skip is a skip whatever the
    # block's layout.
    if not _encoding_supported(column):
        raise TcbError(
            "%s: the file's column uses encoding %d, which this reader cannot decode "
            "for its element type. Regenerate the code or rebuild the data."
            % (field_name, column.encoding))

    if column.element not in accepted:
        raise TcbError(
            "%s: the file carries element type %d, which this member cannot read "
            "(accepts %s). The column changed type incompatibly; regenerate the code or "
            "rebuild the data." % (field_name, column.element, accepted))


def _encoding_supported(column):
    """The (element, encoding) pairs the spec defines.

    Integers take the integer encodings, strings the dictionary ones, and an array takes
    the composition that applies all of those to its elements.
    """
    if column.encoding == ENCODING_RAW:
        return True

    # An array's block says what its elements use, and the element encoding is checked as
    # it is read rather than here - the descriptor carries only the outer one, so this is
    # as far as the descriptor can be checked.
    if column.kind != KIND_SCALAR:
        return column.encoding == ENCODING_ARRAY

    if column.element in (ELEMENT_BOOL, ELEMENT_VARINT):
        return column.encoding in (ENCODING_RLE, ENCODING_BITPACK)

    if column.element == ELEMENT_I32:
        return (ENCODING_VARINT <= column.encoding <= ENCODING_DELTA_RLE
                or column.encoding == ENCODING_BITPACK)

    # The dictionary is parameterized by element, so these three reach it with entries
    # that are simply their own raw bytes.
    if column.element == ELEMENT_I64:
        return column.encoding in (
            ENCODING_DICT, ENCODING_DICT_RLE, ENCODING_BITPACK)

    # A float column additionally reaches the integer encodings, through the block that
    # says its values are whole numbers.
    if column.element in (ELEMENT_F32, ELEMENT_F64):
        return column.encoding in (ENCODING_DICT, ENCODING_DICT_RLE, ENCODING_WHOLE)

    # And a string dictionary can be front coded or built from segments, both of which are
    # meaningless for a fixed-width element and refused for one.
    if column.element == ELEMENT_STRING:
        return (ENCODING_DICT <= column.encoding <= ENCODING_DICT_FRONT_RLE
                or column.encoding in (ENCODING_DICT_SEGMENT, ENCODING_DICT_SEGMENT_RLE))

    return False


def check_block_end(reader, column, expected_end):
    """That a block was consumed exactly.

    A mismatch is a format disagreement, and stopping here names the column instead of
    corrupting the next.
    """
    if reader.position != expected_end:
        raise TcbError(
            "column tag %d: its block declared %d bytes but the read ended %d bytes short "
            "of its boundary" % (column.tag, column.byte_length, expected_end - reader.position))


def _chacha20(key, nonce, data):
    """The keystream of RFC 8439 exclusive-ored over `data`.

    Borrowed rather than written out. Most runtimes carry the cipher themselves - it is
    under two hundred lines and costs them no dependency - but the inner loop is one
    32-bit operation at a time over the whole file, and Python runs that at a speed a
    table file cannot afford. The import is here rather than at the top of the module so
    that a project whose files are not encrypted needs nothing installed.
    """
    try:
        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms
    except ImportError:
        raise TcbError(
            "this file is encrypted, and decrypting one needs the `cryptography` package "
            "- install it with `pip install cryptography`")

    # Its nonce is sixteen bytes: a four-byte little-endian block counter in front of the
    # format's twelve-byte nonce. This format starts the counter at zero.
    cipher = Cipher(
        algorithms.ChaCha20(bytes(key), b"\x00\x00\x00\x00" + bytes(nonce)), mode=None)
    worker = cipher.encryptor()

    return worker.update(bytes(data)) + worker.finalize()


def _check_mac(data, mac_key):
    """The MAC field against the file's own bytes, and against whether a key was given.

    The tag is HMAC-SHA-256 over every byte but the sixteen it lives in, truncated to those
    sixteen. From the standard library, unlike the cipher - `hmac` and `hashlib` are both
    there, so this costs a project nothing.

    What it catches is what the structural checks cannot. A block length that does not add
    up is a malformed file and the reader says so; four other bytes in an f32 column is a
    well-formed file holding a different number, and no check over a file's shape can tell
    that from data that was always there.
    """
    # Nothing to check with. A file that carries a tag is read anyway rather than refused:
    # this reader has no way to tell whether the tag is good, and a client built before the
    # project turned MACs on is one this format has promised can still read what it is sent.
    if mac_key is None or len(mac_key) == 0:
        return

    if len(mac_key) != 32:
        raise TcbError("the MAC key given is not 32 bytes")

    carried = bytes(data[MAC_OFFSET:MAC_OFFSET + MAC_SIZE])

    if carried == b"\x00" * MAC_SIZE:
        raise TcbError(
            "the file carries no MAC and this build expects one - it was exported without "
            "a MAC key, or the field was cleared after it was written")

    tag = hmac.new(bytes(mac_key), digestmod=hashlib.sha256)

    # Two updates: the sixteen bytes the tag lives in cannot be part of what produces it.
    # Skipping them is zeroing them without copying the file.
    tag.update(bytes(data[:MAC_OFFSET]))
    tag.update(bytes(data[KEY_CHECK_OFFSET:]))

    if not hmac.compare_digest(tag.digest()[:MAC_SIZE], carried):
        raise TcbError(
            "the file does not match its MAC - it was altered after it was exported, or "
            "it was signed with a different key")


def open(data, key=None, mac_key=None, verify_mac=True):
    """A file's plaintext bytes, checked against its MAC on the way.

    Call this on the bytes before handing them to a Reader. A file that is neither
    encrypted nor authenticated comes back untouched, so the call belongs in the load path
    whether or not the project uses either.

    The order is verify, then decrypt. The tag covers the file as it is stored, so an
    altered file is refused before the key is used on it, and the header - the flags, the
    cipher byte, the nonce - is covered along with the body.

    What comes back is a file of the same shape, with the fields the envelope wrote
    returned to what a plain file holds in them. Unlike the runtimes that decrypt in place,
    this one hands back a new bytes object: Python's are immutable, and the cipher returns
    its output rather than writing over its input.

    What the two layers are and are not for: both keys ship inside the client that reads
    the file. Encryption stops a data file being read in an editor; the MAC stops an edited
    one loading. Neither stops anyone who can take the keys out of the client, and no
    format does.

    `mac_key` is None when the project does not sign its files. A reader that has one
    refuses a file that carries no MAC: the field being zero is how a file says it is
    unauthenticated, so accepting that from a project that signs its files would put the
    check sixteen zero bytes away from being removed.

    `verify_mac` False skips the check. For tools and for measuring load time - and no
    weaker than it looks, because anyone who can flip this flag in a shipped build can read
    the key out of the same build.
    """
    if len(data) < HEADER_SIZE:
        raise TcbError("the file is too short to be a table")

    if bytes(data[MAGIC_OFFSET:MAGIC_OFFSET + 4]) != MAGIC:
        raise TcbError("the file does not begin with the table file signature")

    if verify_mac:
        _check_mac(data, mac_key)

    if not data[FLAGS_OFFSET] & FLAG_ENCRYPTED:
        return data

    if data[CIPHER_OFFSET] != CIPHER_CHACHA20:
        raise TcbError(
            "the file uses cipher %d, which this reader does not know" % data[CIPHER_OFFSET])

    if key is None or len(key) != 32:
        raise TcbError(
            "the file is encrypted and no key, or a key that is not 32 bytes, was given")

    body = _chacha20(
        key, data[NONCE_OFFSET:NONCE_OFFSET + NONCE_SIZE], data[KEY_CHECK_OFFSET:])

    if body[:4] != MAGIC:
        raise TcbError(
            "the file did not decrypt to a table - the key is not the one it was "
            "written with")

    # Back to what a plain file holds in the fields the envelope wrote, so that a second
    # call over what this returns passes it through instead of decrypting it again.
    header = bytearray(data[:KEY_CHECK_OFFSET])

    header[FLAGS_OFFSET] &= ~FLAG_ENCRYPTED
    header[CIPHER_OFFSET] = CIPHER_NONE
    header[NONCE_OFFSET:NONCE_OFFSET + NONCE_SIZE] = b"\x00" * NONCE_SIZE

    return bytes(header) + body


def read_all_bytes(filename):
    """Reads a whole file into memory."""
    # io.open because this module defines an `open` of its own, which would otherwise be
    # the name reached here.
    with io.open(filename, "rb") as handle:
        return handle.read()
